// Format each Falco alert for Slack
const out = [];
for (const item of $input.all()) {
  const a = item.json.body || item.json;
  const f = a.output_fields || {};
  const emoji = { Emergency: ':rotating_light:', Alert: ':rotating_light:', Critical: ':red_circle:', Error: ':large_orange_circle:', Warning: ':large_yellow_circle:' }[a.priority] || ':information_source:';
  const text = [
    `${emoji} *Falco ${a.priority}* - ${a.rule}`,
    `*Namespace:* ${f['k8s.ns.name'] || 'n/a'}  |  *Pod:* ${f['k8s.pod.name'] || 'n/a'}`,
    `*Container:* ${f['container.name'] || 'n/a'}  |  *Command:* \`${f['proc.cmdline'] || 'n/a'}\``,
    `*Time:* ${a.time}`,
    `*Tags:* ${(a.tags || []).join(', ')}`,
  ].join('\n');
  out.push({ json: { text, priority: a.priority, rule: a.rule } });
}
return out;
